def check_element(test_tup, check_list):
    """The program dawnr proved in `t`, written in Python (checked against `t`, not itself proved).

    ensures  r == (exists i in [0, len(check_list)) . exists j in [0, len(test_tup)) . check_list[i] == test_tup[j])
    """
    if not (_t_ints(test_tup, 1)):
        raise TypeError('check_element: `test_tup` must be a list of integers; nothing was proved for anything else')
    if not (_t_ints(check_list, 1)):
        raise TypeError('check_element: `check_list` must be a list of integers; nothing was proved for anything else')
    test_tup = _t_tuple(test_tup)
    check_list = _t_tuple(check_list)
    _t_result = _t_core(test_tup, check_list)
    return _t_result

def _t_core(test_tup, check_list):
    r = False
    i = 0
    # invariant: 0 <= i
    # invariant: i <= len(check_list)
    # invariant: r ==> (exists k in [0, i) . exists j in [0, len(test_tup)) . check_list[k] == test_tup[j])
    # invariant: not r ==> (forall k in [0, i) . forall j in [0, len(test_tup)) . check_list[k] != test_tup[j])
    # decreases: len(check_list) - i
    while ((i < len(check_list)) and (not r)):
        j = 0
        # invariant: 0 <= j
        # invariant: j <= len(test_tup)
        # invariant: forall k in [0, j) . check_list[i] != test_tup[k]
        # decreases: len(test_tup) - j
        while ((j < len(test_tup)) and (check_list[i] != test_tup[j])):
            j = (j + 1)
        if (j < len(test_tup)):
            r = True
        i = (i + 1)
    return r

def _t_tuple(v):
    return tuple(_t_tuple(x) for x in v) if isinstance(v, (list, tuple)) else v

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

